#!/usr/bin/env bash
# NEX build environment: ESP-IDF + Rust (espup/Xtensa) on one PATH.
#
# Usage:  source tools/env.sh
#
# Reuses the ESP-IDF installation referenced by the user's existing setup and
# never hard-codes a project-relative absolute path.

if [ -f "${HOME}/esp/esp-idf/export.sh" ]; then
    # shellcheck disable=SC1091
    . "${HOME}/esp/esp-idf/export.sh"
else
    echo "error: ESP-IDF not found at \$HOME/esp/esp-idf/export.sh" >&2
    return 1 2>/dev/null || exit 1
fi

export PATH="${HOME}/.cargo/bin:${PATH}"

# Generated by `espup install`; provides the Xtensa GCC on PATH and
# LIBCLANG_PATH. Not required for cargo-only checks, required for full builds.
if [ -f "${HOME}/export-esp.sh" ]; then
    # shellcheck disable=SC1091
    . "${HOME}/export-esp.sh"
fi
